insert into purchase(
	purchase_no, purchase_name,
	purchase_total, purchase_remain,
	purchase_owner, purchase_tid
)
values(
	#{purchaseNo}, #{purchaseName},
	#{purchaseTotal}, #{purchaseRemain},
	#{purchaseOwner}, #{purchaseTid}
)

insert into purchase_detail (
	purchase_detail_no, purchase_detail_origin,
	purchase_detail_item, purchase_detail_name,
	purchase_detail_price, purchase_detail_qty
)
values(
	#{purchaseDetailNo}, #{purchaseDetailOrigin},
	#{purchaseDetailItem}, #{purchaseDetailName},
	#{purchaseDetailPrice}, #{purchaseDetailQty}
)

mapper.select:
select * from purchase_detail
where purchase_detail_origin = #{purchaseDetailOrigin}
order by purchase_detail_no asc

mapper.update:
update 	purchase_detail
set 	purchase_detail_status = '취소'
where 	purchase_detail_origin = #{purchaseDetailOrigin}

update 	purchase_detail
set 	purchase_detail_status = '취소'
where 	purchase_detail_no = #{purchaseDetailNo}
